/**
 * Circuit layout contract (F1-046). Generated by `scripts/build-circuits.mjs`
 * from the MIT-licensed bacinger/f1-circuits GeoJSON dataset.
 *
 * Coordinate system: metres in a local tangent plane around the circuit
 * centroid. x = east, y = north. The 3D layer maps (x, y) → (x, 0, -y).
 * Positions are approximate (F1-004) and never presented as exact lines.
 */

export type Vec2 = [number, number];

export type EnvironmentTheme =
  | 'desert'        // Bahrain, Qatar, Abu Dhabi, Jeddah
  | 'street'        // Monaco, Baku, Singapore, Las Vegas, Miami, Madrid
  | 'parkland'      // Melbourne, Montreal, Mexico City
  | 'forest'        // Spa, Monza, Red Bull Ring, Hungaroring
  | 'countryside'   // Silverstone, Suzuka, Barcelona, Shanghai, Interlagos, Austin
  | 'dunes';        // Zandvoort

export type TimeOfDay = 'day' | 'dusk' | 'night';

export type LandmarkKind =
  | 'yas-hotel'        // Abu Dhabi — LED gridshell hotel over the track
  | 'ferris-wheel'     // Suzuka
  | 'harbour'          // Monaco — yachts in the harbour
  | 'marina'           // Abu Dhabi / Miami — boats
  | 'sphere'           // Las Vegas
  | 'towers'           // Baku / Jeddah / Singapore skyline
  | 'sakhir-tower'     // Bahrain — tower at start/finish
  | 'stadium'          // Mexico City — Foro Sol
  | 'observation-tower'// Austin
  | 'mountains'        // Spa / Red Bull Ring backdrop
  | 'lake'             // Melbourne Albert Park / Montreal basin
  | 'bridge';          // Suzuka crossover / Singapore

export interface LandmarkSpec {
  kind: LandmarkKind;
  /** Local position in metres. */
  position: Vec2;
  /** Heading in radians (0 = +x). */
  rotation: number;
  /** Relative size multiplier. */
  scale: number;
}

export interface CircuitSector {
  index: 1 | 2 | 3;
  /** Arc length (m) along centerline from the control line. */
  startS: number;
  endS: number;
}

export interface CircuitCorner {
  number: number;
  /** Arc length (m) of the apex. */
  s: number;
  direction: 'L' | 'R';
  /** 1 = flat-out kink … 6 = hairpin (from curvature). */
  severity: 1 | 2 | 3 | 4 | 5 | 6;
  /** Minimum radius in metres at the apex. */
  radius: number;
  name?: string;
}

export interface StraightZone {
  /** Overtake/aero activation zone (2026: Straight Mode / Overtake Mode zones). */
  detectionS: number;
  startS: number;
  endS: number;
}

export interface PitLaneData {
  /** Polyline in race direction, metres, from pit entry to pit exit, spacing ~4 m. */
  path: Vec2[];
  /** Arc length on the main centerline where the pit lane leaves / rejoins. */
  entryS: number;
  exitS: number;
  /** Arc length along `path` where the boxes (garage row) start and end. */
  boxesStartS: number;
  boxesEndS: number;
  /** Which side of the main straight (in race direction). */
  side: 'left' | 'right';
  speedLimitKph: number;
  lengthM: number;
}

export interface GrandstandSpec {
  /** Arc length along the centerline of the stand centre. */
  s: number;
  side: 'left' | 'right';
  lengthM: number;
  /** Rows of seats (height). */
  rows: number;
  /** Distance from the track centerline to the front of the stand. */
  offsetM: number;
  name?: string;
}

export interface CircuitData {
  /** Dataset id, e.g. 'ae-2009'. */
  id: string;
  /** Versioned layout id stored on pools (F1-005, F1-046). */
  layoutVersion: string;
  name: string;
  /** Short display name, e.g. 'Yas Marina'. */
  shortName: string;
  location: string;
  country: string;
  /** ISO 3166-1 alpha-2 for flags. */
  countryCode: string;
  timezone: string;
  /** Official lap length in metres (display). */
  lengthM: number;
  /** Length of the generated centerline in metres. */
  centerlineLengthM: number;
  laps: number;
  sprintLaps?: number;
  direction: 'CW' | 'CCW';
  /** Track width in metres. */
  widthM: number;
  /** Closed loop, uniform spacing (~4 m), index 0 on the control line, race direction. */
  centerline: Vec2[];
  /** Spacing between centerline points in metres. */
  spacingM: number;
  sectors: [CircuitSector, CircuitSector, CircuitSector];
  corners: CircuitCorner[];
  straightZones: StraightZone[];
  pitLane: PitLaneData;
  grandstands: GrandstandSpec[];
  bounds: { minX: number; maxX: number; minY: number; maxY: number };
  theme: EnvironmentTheme;
  timeOfDay: TimeOfDay;
  landmarks: LandmarkSpec[];
  /** Ground under the circuit: 'sand' | 'grass' | 'asphalt' | 'water' patches handled by the scene builder. */
  hasWater: boolean;
  lapRecordMs: number | null;
}

/** Lightweight descriptor (no geometry) for lists and the calendar. */
export interface CircuitMeta {
  id: string;
  name: string;
  shortName: string;
  location: string;
  country: string;
  countryCode: string;
  lengthM: number;
  laps: number;
  direction: 'CW' | 'CCW';
  theme: EnvironmentTheme;
  timeOfDay: TimeOfDay;
  /** Normalised SVG path (viewBox 0 0 100 100) for thumbnails. */
  svgPath: string;
}
